import json
import math

# Exact integer arithmetic only. Sides: a (unknown), 68, 60. Area: 960.
B, C, AREA = 68, 60, 960

b2, c2 = B * B, C * C
K = 16 * AREA * AREA  # 16*Area^2 from Heron's formula

# Heron in terms of x = a^2:
#   16*Area^2 = -x^2 + 2x(b2+c2) - (b2-c2)^2
# so x^2 - 2(b2+c2)x + ((b2-c2)^2 + K) = 0
# Roots: x = (b2+c2) +/- sqrt(4*b2*c2 - K)
disc_half = 4 * b2 * c2 - K
s = math.isqrt(disc_half) if disc_half >= 0 else None
evidence = {
    "b2": b2, "c2": c2, "K_16A2": K,
    "disc_half": disc_half,
}

def simplify_sqrt(n):
    """Return (k, m) with sqrt(n) = k*sqrt(m), m squarefree."""
    for k in range(math.isqrt(n), 0, -1):
        if n % (k * k) == 0:
            return k, n // (k * k)
    return 1, n

candidates = []
if s is not None and s * s == disc_half:
    for x in sorted({(b2 + c2) + s, (b2 + c2) - s}):
        if x <= 0:
            continue
        # Verify exactly: Heron's 16A^2 with a^2 = x must equal K
        heron16 = 2*x*b2 + 2*x*c2 + 2*b2*c2 - x*x - b2*b2 - c2*c2 - x*0
        if heron16 != K:
            continue
        # Positive Heron value => non-degenerate triangle
        if heron16 <= 0:
            continue
        k, m = simplify_sqrt(x)
        if m == 1:
            label = str(k)
        elif k == 1:
            label = f"sqrt({m})"
        else:
            label = f"{k}*sqrt({m})"
        candidates.append({"a_squared": x, "a": label,
                           "a_approx": round(math.sqrt(x), 6)})

evidence["candidates"] = candidates
evidence["count"] = len(candidates)

if candidates:
    final = " or ".join(c["a"] for c in candidates)
else:
    final = "UNSUPPORTED"

print(json.dumps({"final_answer": final, "evidence": evidence},
                 separators=(",", ":")))
